1	import {
2	  runScenario,
3	  type Scenario,
4	  type ScenarioResults,
5	} from "./claim-office.js";
6	
7	/** The scenario arrives as one JSON document, so stdin is read to the end. */
8	const readStdin = async (): Promise<string> => {
9	  const chunks: Buffer[] = [];
10	
11	  for await (const chunk of process.stdin) {
12	    chunks.push(chunk as Buffer);
13	  }
14	
15	  return Buffer.concat(chunks).toString("utf8");
16	};
17	
18	const readScenario = async (): Promise<Scenario> =>
19	  JSON.parse(await readStdin()) as Scenario;
20	
21	const writeResults = (results: ScenarioResults): void => {
22	  process.stdout.write(JSON.stringify(results));
23	};
24	
25	/** A rejected scenario is reported to stderr; stdout stays empty. */
26	const reject = (error: unknown): never => {
27	  process.stderr.write(`${error instanceof Error ? error.message : error}\n`);
28	  process.exit(1);
29	};
30	
31	try {
32	  writeResults(runScenario(await readScenario()));
33	} catch (error) {
34	  reject(error);
35	}
