1	import { describe, it, expect } from "vitest";
2	import { spawnSync } from "node:child_process";
3	
4	const runCli = (input: string) =>
5	  spawnSync("npx", ["tsx", "src/cli.ts"], { input, encoding: "utf8" });
6	
7	describe("claim-office CLI", () => {
8	  it("reads a scenario from stdin and writes the results to stdout", () => {
9	    const scenario = {
10	      customer: { yearsWithMHPCO: 5 },
11	      steps: [
12	        {
13	          op: "quote",
14	          items: [
15	            { type: "amulet", material: "silver", enchantment: 2, cursed: false },
16	          ],
17	        },
18	        {
19	          op: "claim",
20	          policy: 0,
21	          incident: { cause: "fire", damages: [{ itemType: "amulet", amount: 200 }] },
22	        },
23	      ],
24	    };
25	
26	    const cli = runCli(JSON.stringify(scenario));
27	
28	    expect(cli.status).toBe(0);
29	    expect(JSON.parse(cli.stdout)).toEqual({
30	      results: [{ premium: 59 }, { payout: 100, remainingCap: 1100 }],
31	    });
32	  });
33	
34	  it("exits non-zero and writes to stderr when an item type is unknown", () => {
35	    const cli = runCli(
36	      JSON.stringify({
37	        customer: { yearsWithMHPCO: 0 },
38	        steps: [{ op: "quote", items: [{ type: "broomstick" }] }],
39	      }),
40	    );
41	
42	    expect(cli.status).not.toBe(0);
43	    // an error description, not a stack trace
44	    expect(cli.stderr.trim()).toBe("unknown item type: broomstick");
45	  });
46	  it.todo("writes no results to stdout when the scenario is rejected");
47	});
