1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Damage {
14	  itemType: string;
15	  amount: number;
16	}
17	
18	export interface Incident {
19	  cause: string;
20	  damages: Damage[];
21	}
22	
23	export interface ClaimStep {
24	  op: "claim";
25	  /** Zero-based index of the quote step that created the policy. */
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export type Step = QuoteStep | ClaimStep;
31	
32	export interface Customer {
33	  yearsWithMHPCO: number;
34	}
35	
36	export interface Scenario {
37	  customer: Customer;
38	  steps: Step[];
39	}
40	
41	export interface QuoteResult {
42	  premium: number;
43	}
44	
45	export interface ClaimResult {
46	  payout: number;
47	  remainingCap: number;
48	}
49	
50	export interface ScenarioResults {
51	  results: (QuoteResult | ClaimResult)[];
52	}
53	
54	const PROCESSING_FEE = 5;
55	const FIRST_INSURANCE_SURCHARGE = 0.1;
56	const CURSE_SURCHARGE = 0.5;
57	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
58	const HIGH_ENCHANTMENT_THRESHOLD = 5;
59	const LOYALTY_DISCOUNT = 0.2;
60	const LOYALTY_THRESHOLD_YEARS = 2;
61	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
62	
63	/** Premiums are rounded up (in the MHPCO's favour), ignoring float noise. */
64	const roundUp = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
65	
66	/** The two rates the tariff sets for each item type. */
67	interface ItemTariff {
68	  basePremium: number;
69	  insuranceValue: number;
70	}
71	
72	/** The item types the MHPCO insures. Any other type is unknown to the tariff. */
73	const TARIFF: Record<string, ItemTariff> = {
74	  sword: { basePremium: 100, insuranceValue: 1000 },
75	  amulet: { basePremium: 60, insuranceValue: 600 },
76	  staff: { basePremium: 80, insuranceValue: 800 },
77	  potion: { basePremium: 40, insuranceValue: 400 },
78	  rune: { basePremium: 25, insuranceValue: 250 },
79	  moonstone: { basePremium: 25, insuranceValue: 250 },
80	};
81	
82	const DEDUCTIBLE = 100;
83	const CAP_MULTIPLIER = 2;
84	const STRONG_ENCHANTMENT_THRESHOLD = 8;
85	const STRONG_ENCHANTMENT_REIMBURSEMENT = 0.5;
86	
87	const COMPONENT_TYPES = ["rune", "moonstone"];
88	const BLOCK_SIZE = 3;
89	const BLOCK_BASE_PREMIUM = 60;
90	
91	const isComponent = (type: string): boolean => COMPONENT_TYPES.includes(type);
92	
93	/** How often each type occurs, for pricing alike items and matching damages. */
94	const countByType = (types: string[]): Map<string, number> => {
95	  const counts = new Map<string, number>();
96	
97	  for (const type of types) {
98	    counts.set(type, (counts.get(type) ?? 0) + 1);
99	  }
100	
101	  return counts;
102	};
103	
104	const itemTypes = (items: Item[]): string[] => items.map((item) => item.type);
105	
106	const damagedTypes = (incident: Incident): string[] =>
107	  incident.damages.map((damage) => damage.itemType);
108	
109	/** Exactly BLOCK_SIZE alike components form a building block. */
110	const formsBuildingBlock = (type: string, count: number): boolean =>
111	  isComponent(type) && count === BLOCK_SIZE;
112	
113	const tariffFor = (type: string): ItemTariff => {
114	  const tariff = TARIFF[type];
115	
116	  if (tariff === undefined) {
117	    throw new Error(`unknown item type: ${type}`);
118	  }
119	
120	  return tariff;
121	};
122	
123	const itemBasePremium = (type: string): number => tariffFor(type).basePremium;
124	
125	const itemInsuranceValue = (type: string): number => tariffFor(type).insuranceValue;
126	
127	/** Alike items are priced together so a building block can be recognised. */
128	const groupBasePremium = (type: string, count: number): number =>
129	  formsBuildingBlock(type, count)
130	    ? BLOCK_BASE_PREMIUM
131	    : count * itemBasePremium(type);
132	
133	/** The policy base premium is the sum of the base premiums of its items. */
134	const policyBasePremium = (items: Item[]): number =>
135	  [...countByType(itemTypes(items))].reduce(
136	    (total, [type, count]) => total + groupBasePremium(type, count),
137	    0,
138	  );
139	
140	const isCursed = (item: Item): boolean => item.cursed === true;
141	
142	const isHighlyEnchanted = (item: Item): boolean =>
143	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
144	
145	/**
146	 * Item-specific surcharges stack additively, as fractions of the item's base
147	 * premium.
148	 */
149	const itemSurchargeRate = (item: Item): number =>
150	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
151	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
152	
153	/**
154	 * Item-specific modifiers apply to the base premium of the affected item,
155	 * not to the policy total.
156	 */
157	const itemSurcharges = (items: Item[]): number =>
158	  items.reduce(
159	    (total, item) =>
160	      total + itemBasePremium(item.type) * itemSurchargeRate(item),
161	    0,
162	  );
163	
164	const isLoyalCustomer = (customer: Customer): boolean =>
165	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
166	
167	/**
168	 * Policy-wide modifiers, as fractions of the policy base premium. Each is an
169	 * amount added to (or, when negative, subtracted from) that base premium, so
170	 * modifiers stack additively rather than compounding.
171	 */
172	const policyModifierRates = (
173	  customer: Customer,
174	  isFollowUpContract: boolean,
175	): number[] => [
176	  FIRST_INSURANCE_SURCHARGE,
177	  isLoyalCustomer(customer) ? -LOYALTY_DISCOUNT : 0,
178	  isFollowUpContract ? -FOLLOW_UP_CONTRACT_DISCOUNT : 0,
179	];
180	
181	const policyModifiers = (
182	  basePremium: number,
183	  customer: Customer,
184	  isFollowUpContract: boolean,
185	): number =>
186	  policyModifierRates(customer, isFollowUpContract).reduce(
187	    (total, rate) => total + basePremium * rate,
188	    0,
189	  );
190	
191	const quotePremium = (
192	  step: QuoteStep,
193	  customer: Customer,
194	  isFollowUpContract: boolean,
195	): number => {
196	  const basePremium = policyBasePremium(step.items);
197	
198	  return roundUp(
199	    basePremium +
200	      itemSurcharges(step.items) +
201	      policyModifiers(basePremium, customer, isFollowUpContract) +
202	      PROCESSING_FEE,
203	  );
204	};
205	
206	/**
207	 * Every contract after the customer's first is a follow-up. Only quote steps
208	 * create contracts, so this counts preceding quotes rather than preceding steps.
209	 */
210	const isFollowUpContract = (precedingSteps: Step[]): boolean =>
211	  precedingSteps.some((step) => step.op === "quote");
212	
213	/** Payouts are rounded down (in the MHPCO's favour), ignoring float noise. */
214	const roundDown = (amount: number): number =>
215	  Math.floor(Number(amount.toFixed(6)));
216	
217	/** The insurance sum is the sum of the items' insurance values. */
218	const insuranceSum = (items: Item[]): number =>
219	  items.reduce((total, item) => total + itemInsuranceValue(item.type), 0);
220	
221	const isStronglyEnchanted = (item: Item): boolean =>
222	  (item.enchantment ?? 0) >= STRONG_ENCHANTMENT_THRESHOLD;
223	
224	/**
225	 * The reimbursement clauses decide how much of the damage is reimbursed,
226	 * before the deductible is applied.
227	 */
228	const reimbursementRate = (item: Item): number =>
229	  isStronglyEnchanted(item) ? STRONG_ENCHANTMENT_REIMBURSEMENT : 1;
230	
231	const damagePayout = (damage: Damage, item: Item): number => {
232	  if (damage.amount < 0) {
233	    throw new Error(`negative damage amount: ${damage.amount}`);
234	  }
235	
236	  return Math.max(0, damage.amount * reimbursementRate(item) - DEDUCTIBLE);
237	};
238	
239	/** A policy pays out at most CAP_MULTIPLIER times its insurance sum. */
240	const policyCap = (policy: QuoteStep): number =>
241	  insuranceSum(policy.items) * CAP_MULTIPLIER;
242	
243	/** The insured item a damage entry refers to, matched by item type. */
244	const damagedItem = (damage: Damage, items: Item[]): Item => {
245	  const item = items.find((insured) => insured.type === damage.itemType);
246	
247	  if (item === undefined) {
248	    throw new Error(`item not covered by the policy: ${damage.itemType}`);
249	  }
250	
251	  return item;
252	};
253	
254	/**
255	 * A damage entry stands for one damaged item, so a type cannot be damaged more
256	 * often than the policy covers it. The whole claim is rejected if it is.
257	 */
258	const rejectExcessDamages = (incident: Incident, items: Item[]): void => {
259	  const insured = countByType(itemTypes(items));
260	
261	  for (const [type, damaged] of countByType(damagedTypes(incident))) {
262	    if (damaged > (insured.get(type) ?? 0)) {
263	      throw new Error(`more ${type} damages than the policy covers`);
264	    }
265	  }
266	};
267	
268	const incidentPayout = (incident: Incident, items: Item[]): number =>
269	  roundDown(
270	    incident.damages.reduce(
271	      (total, damage) => total + damagePayout(damage, damagedItem(damage, items)),
272	      0,
273	    ),
274	  );
275	
276	/** The payout is limited to what remains of the policy's cap. */
277	const claimResult = (
278	  incident: Incident,
279	  policy: QuoteStep,
280	  remainingCap: number,
281	): ClaimResult => {
282	  rejectExcessDamages(incident, policy.items);
283	
284	  const payout = Math.min(incidentPayout(incident, policy.items), remainingCap);
285	
286	  return { payout, remainingCap: remainingCap - payout };
287	};
288	
289	/**
290	 * A scenario is walked step by step, because a claim draws on what earlier
291	 * claims left of its policy's cap. The caps of the policies quoted so far are
292	 * the only state carried from one step to the next.
293	 */
294	type RemainingCaps = Map<number, number>;
295	
296	const quoteStepResult = (
297	  step: QuoteStep,
298	  index: number,
299	  scenario: Scenario,
300	  remainingCaps: RemainingCaps,
301	): QuoteResult => {
302	  remainingCaps.set(index, policyCap(step));
303	
304	  return {
305	    premium: quotePremium(
306	      step,
307	      scenario.customer,
308	      isFollowUpContract(scenario.steps.slice(0, index)),
309	    ),
310	  };
311	};
312	
313	/** A claim draws on a policy, so its step index must name an earlier quote. */
314	const policyFor = (step: ClaimStep, scenario: Scenario): QuoteStep => {
315	  const quoted = scenario.steps[step.policy];
316	
317	  if (quoted === undefined || quoted.op !== "quote") {
318	    throw new Error(`claim does not refer to a policy: step ${step.policy}`);
319	  }
320	
321	  return quoted;
322	};
323	
324	const claimStepResult = (
325	  step: ClaimStep,
326	  scenario: Scenario,
327	  remainingCaps: RemainingCaps,
328	): ClaimResult => {
329	  const policy = policyFor(step, scenario);
330	  const result = claimResult(
331	    step.incident,
332	    policy,
333	    remainingCaps.get(step.policy) ?? policyCap(policy),
334	  );
335	
336	  remainingCaps.set(step.policy, result.remainingCap);
337	
338	  return result;
339	};
340	
341	export const runScenario = (scenario: Scenario): ScenarioResults => {
342	  const remainingCaps: RemainingCaps = new Map();
343	
344	  return {
345	    results: scenario.steps.map((step, index) =>
346	      step.op === "quote"
347	        ? quoteStepResult(step, index, scenario, remainingCaps)
348	        : claimStepResult(step, scenario, remainingCaps),
349	    ),
350	  };
351	};
